head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     River Musa
Version:  1.0.0
License:  Free to use on any Blogger blog
----------------------------------------------- */

/* Variable definitions (editable in Theme > Customize > Advanced)
====================
<Variable name="primary.color" description="Primary (header, hero, footer)" type="color" default="#0D1C2E" value="#0D1C2E"/>
<Variable name="primary.soft.color" description="Cards on the primary colour" type="color" default="#17263A" value="#17263A"/>
<Variable name="accent.color" description="Accent (buttons, highlights)" type="color" default="#00C0A8" value="#00C0A8"/>
<Variable name="accent.hover.color" description="Accent hover" type="color" default="#33D4C0" value="#33D4C0"/>
<Variable name="page.background.color" description="Page background" type="color" default="#F5F7FA" value="#F5F7FA"/>
<Variable name="text.color" description="Body text" type="color" default="#1C2B3A" value="#1C2B3A"/>
<Variable name="muted.color" description="Muted text" type="color" default="#6B7A8D" value="#6B7A8D"/>
<Variable name="border.color" description="Borders and dividers" type="color" default="#DDE2EA" value="#DDE2EA"/>
*/



/* ---------- Base ---------- */
*, *::before, *::after { box-sizing: border-box; }
html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: calc(68px + 12px);
}
body {
  margin: 0;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 16px;
  line-height: 1.65;
  color: $(text.color);
  background: $(page.background.color);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
html.nav-locked, html.nav-locked body { overflow: hidden; }
img, video, iframe, embed, object { max-width: 100%; }
img { height: auto; border: 0; }
a { color: inherit; text-decoration: none; }
p { margin: 0 0 1em; }
h1, h2, h3, h4, h5, h6 { margin: 0 0 0.5em; line-height: 1.15; color: inherit; }
button, input, select, textarea { font: inherit; color: inherit; }
/* "body" prefix: Blogger injects its own widget stylesheet, sometimes after this skin */
body .section, body .widget { margin: 0; padding: 0; }
body .widget ul, body .widget ol { list-style: none; margin: 0; padding: 0; }
body .widget li { margin: 0; padding: 0; }
:focus-visible { outline: 2px solid $(accent.color); outline-offset: 3px; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}
@media (min-width: 768px) { .container { padding: 0 32px; } }

.skip-link {
  position: absolute;
  left: -9999px;
  top: 12px;
  z-index: 300;
  background: #fff;
  color: $(primary.color);
  font-weight: 700;
  padding: 10px 16px;
  border-radius: 8px;
}
.skip-link:focus { left: 16px; }

.badge {
  display: inline-block;
  background: $(accent.color);
  color: $(primary.color);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 4px;
  transition: background 0.2s, color 0.2s;
}
a.badge:hover { background: $(primary.color); color: $(accent.color); }

/* ---------- Buttons ---------- */
.btn,
.header-cta .widget-content a,
.hero-main .widget-content a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 12px 26px;
  border: 2px solid transparent;
  border-radius: 8px;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.3px;
  text-align: center;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.2s;
}
.btn-primary,
.header-cta .widget-content a,
.hero-main .widget-content li:first-child a {
  background: $(accent.color);
  border-color: $(accent.color);
  color: $(primary.color);
}
.btn-primary:hover,
.header-cta .widget-content a:hover,
.hero-main .widget-content li:first-child a:hover {
  background: $(accent.hover.color);
  border-color: $(accent.hover.color);
  color: $(primary.color);
}
.hero-main .widget-content li a {
  background: transparent;
  border-color: rgba(255, 255, 255, 0.55);
  color: #fff;
}
.hero-main .widget-content li a:hover { border-color: $(accent.color); color: $(accent.color); }
.btn-outline {
  background: transparent;
  border-color: $(border.color);
  color: $(primary.color);
}
.btn-outline:hover { border-color: $(primary.color); }

/* ---------- Header ---------- */
.site-header {
  position: -webkit-sticky;
  position: sticky;
  top: 0;
  z-index: 100;
  background: $(primary.color);
  border-bottom: 2px solid $(accent.color);
  transition: box-shadow 0.2s;
}
.site-header.is-scrolled { box-shadow: 0 6px 20px rgba(0, 0, 0, 0.28); }
.header-inner {
  position: relative;
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 68px;
}
.brand-section { flex: 1 1 auto; min-width: 0; }
.brand { display: flex; align-items: center; gap: 10px; color: #fff; }
.brand:hover { color: #fff; }
.brand-mark {
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: $(accent.color);
  color: $(primary.color);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 0.5px;
  overflow: hidden;
}
.brand-mark img { width: 100%; height: 100%; object-fit: cover; }
.brand-logo img { display: block; max-height: 44px; width: auto; }
.brand-text { display: flex; flex-direction: column; min-width: 0; }
.brand-name {
  font-size: 17px;
  font-weight: 700;
  line-height: 1.2;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.brand-tagline {
  font-size: 12px;
  line-height: 1.35;
  color: $(accent.color);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.nav-toggle {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin-right: -8px;
  padding: 0;
  background: none;
  border: 0;
  border-radius: 8px;
  color: #fff;
  cursor: pointer;
}
.nav-toggle:hover { color: $(accent.color); }
.nav-toggle svg { display: block; }
.nav-toggle .icon-close { display: none; }
.site-header.nav-open .nav-toggle .icon-menu { display: none; }
.site-header.nav-open .nav-toggle .icon-close { display: block; }

/* Dimmed page behind the open phone menu (tap to close) */
.nav-backdrop {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 90;
  background: rgba(5, 12, 22, 0.6);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s, visibility 0.2s;
}
.nav-backdrop.is-visible { opacity: 1; visibility: visible; }
@media (min-width: 1024px) { .nav-backdrop { display: none; } }

/* Mobile drawer */
.nav-drawer { display: none; }
.site-header.nav-open .nav-drawer {
  display: block;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  margin-top: 2px;
  padding: 8px 20px 24px;
  background: $(primary.color);
  border-bottom: 2px solid $(accent.color);
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.3);
  max-height: calc(100vh - 68px);
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}
.site-nav .widget > .title, .site-nav .widget > h2, .site-nav .widget > h3,
.header-cta .widget > .title, .header-cta .widget > h2, .header-cta .widget > h3 { display: none; }
.site-nav li a {
  display: block;
  padding: 14px 4px;
  font-size: 16px;
  font-weight: 700;
  color: #E6ECF3;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  transition: color 0.2s, border-color 0.2s;
}
.site-nav li a:hover { color: $(accent.color); }
.header-cta .widget-content { margin-top: 18px; }
.header-cta .widget-content a { display: flex; width: 100%; }

@media (min-width: 1024px) {
  .nav-toggle { display: none; }
  .nav-drawer,
  .site-header.nav-open .nav-drawer {
    display: flex;
    align-items: center;
    gap: 28px;
    position: static;
    margin: 0;
    padding: 0;
    background: none;
    border: 0;
    box-shadow: none;
    max-height: none;
    overflow: visible;
  }
  .site-nav .widget-content > ul { display: flex; align-items: center; gap: 26px; }
  .site-nav li a {
    padding: 6px 0;
    font-size: 15px;
    border-bottom: 2px solid transparent;
  }
  .site-nav li a:hover { border-bottom-color: $(accent.color); }
  .header-cta .widget-content { margin: 0; }
  .header-cta .widget-content a { display: inline-flex; width: auto; min-height: 40px; padding: 9px 18px; font-size: 14px; }
}

/* Sub-menus (Link List items starting with "_") */
.site-nav li.has-sub { position: relative; display: flex; flex-wrap: wrap; align-items: center; border-bottom: 1px solid rgba(255, 255, 255, 0.08); }
.site-nav li.has-sub > a { flex: 1 1 auto; border-bottom: 0; }
.site-nav .sub-menu li:last-child a { border-bottom: 0; }
.sub-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  margin: 0;
  padding: 0;
  background: none;
  border: 0;
  color: #E6ECF3;
  cursor: pointer;
  transition: color 0.2s, transform 0.2s;
}
.sub-toggle:hover { color: $(accent.color); }
.site-nav li.open > .sub-toggle { transform: rotate(180deg); color: $(accent.color); }
body .widget .site-nav .sub-menu,
.site-nav .sub-menu {
  display: none;
  flex-basis: 100%;
  margin: 0 0 8px;
  padding: 0 0 0 14px;
  border-left: 2px solid $(accent.color);
}
.site-nav li.open > .sub-menu { display: block; }
.site-nav .sub-menu li a {
  padding: 11px 4px;
  font-size: 15px;
  font-weight: 600;
  color: #C9D2E0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
@media (min-width: 1024px) {
  .site-nav li.has-sub { flex-wrap: nowrap; border-bottom: 0; }
  .site-nav li.has-sub > a { border-bottom: 2px solid transparent; }
  .site-nav li.has-sub > a:hover { border-bottom-color: $(accent.color); }
  .sub-toggle { width: 22px; height: 22px; margin-left: 2px; }
  body .widget .site-nav .sub-menu,
  .site-nav .sub-menu {
    display: block;
    position: absolute;
    top: 100%;
    left: -16px;
    z-index: 120;
    min-width: 230px;
    margin: 0;
    padding: 8px 0;
    background: $(primary.color);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-top: 2px solid $(accent.color);
    border-radius: 0 0 8px 8px;
    box-shadow: 0 16px 32px rgba(0, 0, 0, 0.3);
    visibility: hidden;
    opacity: 0;
    transform: translateY(6px);
    transition: opacity 0.18s, transform 0.18s, visibility 0.18s;
  }
  .site-nav li.has-sub:hover > .sub-menu,
  .site-nav li.has-sub:focus-within > .sub-menu,
  .site-nav li.has-sub.open > .sub-menu { visibility: visible; opacity: 1; transform: translateY(0); }
  .site-nav li.has-sub:hover > .sub-toggle { color: $(accent.color); }
  .site-nav .sub-menu li a {
    display: block;
    padding: 9px 18px;
    font-size: 14px;
    white-space: nowrap;
    border-bottom: 0;
  }
  .site-nav .sub-menu li a:hover { background: rgba(0, 192, 168, 0.08); border-bottom-color: transparent; }
}

/* ---------- Hero (homepage) ---------- */
.hero {
  display: none;
  position: relative;
  overflow: hidden;
  background: $(primary.color);
  color: #fff;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(55% 60% at 78% 45%, rgba(0, 192, 168, 0.10), rgba(0, 192, 168, 0) 70%);
  pointer-events: none;
}
.hero-inner {
  position: relative;
  display: flex;
  align-items: center;
  min-height: calc(92vh - 68px);
  min-height: calc(92svh - 68px);
  padding-top: 64px;
  padding-bottom: 72px;
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 32px;
  width: 100%;
}
.hero .widget > h2.title { display: none; }
.hero-main .widget + .widget { margin-top: 28px; }
.hero-eyebrow {
  margin: 0 0 18px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 3px;
  line-height: 1.5;
  text-transform: uppercase;
  color: $(accent.color);
}
.hero-title {
  position: relative;
  margin: 0 0 24px;
  padding-left: 18px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: clamp(46px, 8vw, 84px);
  line-height: 0.95;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #fff;
}
.hero-title::before {
  content: '';
  position: absolute;
  left: 0;
  top: 4px;
  bottom: 4px;
  width: 4px;
  border-radius: 2px;
  background: linear-gradient(to bottom, #1A7BC4, $(accent.color));
}
.hero-title .accent { color: $(accent.color); }
.hero-text { max-width: 560px; font-size: 17px; line-height: 1.75; color: #C9D2E0; }
.hero-text p:last-child { margin-bottom: 0; }
.hero-text a { color: $(accent.color); text-decoration: underline; }
.hero-main .widget-content ul { display: flex; flex-wrap: wrap; gap: 12px; }

.host-card {
  display: block;
  width: 100%;
  max-width: 420px;
  margin: 0 auto;
  padding: 36px 24px;
  text-align: center;
  background: $(primary.soft.color);
  border: 1px solid rgba(255, 255, 255, 0.10);
  border-radius: 16px;
  color: #fff;
}
a.host-card:hover { border-color: rgba(0, 192, 168, 0.5); color: #fff; }
.host-avatar {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 112px;
  height: 112px;
  margin: 0 auto 18px;
  border-radius: 50%;
  border: 3px solid $(accent.color);
  background: rgba(0, 192, 168, 0.12);
  color: #fff;
  overflow: hidden;
}
.host-avatar img { width: 100%; height: 100%; object-fit: cover; }
.host-name { margin: 0 0 4px; font-size: 20px; font-weight: 700; color: #fff; }
.host-card.has-video { max-width: 520px; padding: 16px 16px 26px; }
.host-video {
  position: relative;
  width: 100%;
  margin: 0 0 18px;
  padding-top: 56.25%;
  border-radius: 12px;
  overflow: hidden;
  background: #000;
}
.host-video iframe,
.host-video-play {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
}
.host-video-play { display: block; padding: 0; background: #000; cursor: pointer; }
.host-video-play img { width: 100%; height: 100%; object-fit: cover; opacity: 0.85; transition: opacity 0.2s; }
.host-video-play:hover img { opacity: 1; }
.host-video-icon {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 64px;
  height: 64px;
  margin: -32px 0 0 -32px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-left: 4px;
  border-radius: 50%;
  background: $(accent.color);
  color: $(primary.color);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.35);
  transition: transform 0.2s, background 0.2s;
}
.host-video-play:hover .host-video-icon,
.host-video-play:focus-visible .host-video-icon { transform: scale(1.08); background: $(accent.hover.color); }
.host-role { font-size: 14px; font-weight: 600; color: $(accent.color); }
.host-role p { margin: 0; }

@media (min-width: 960px) {
  .hero-grid {
    grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
    column-gap: 72px;
    align-items: center;
  }
  .host-card { padding: 44px 28px; }
}

/* ---------- Main content ---------- */
.page-main { padding: 48px 0 64px; }
@media (min-width: 768px) { .page-main { padding: 64px 0 80px; } }
.main-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 40px; }
@media (min-width: 1024px) {
  .pt-item .main-grid,
  .pt-static_page .main-grid { grid-template-columns: minmax(0, 1fr) 320px; }
}

.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 28px;
}
.section-title {
  display: inline-block;
  margin: 0;
  padding-bottom: 6px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: clamp(30px, 4vw, 42px);
  letter-spacing: 1.5px;
  line-height: 1;
  color: $(primary.color);
  border-bottom: 3px solid $(accent.color);
}

.search-form { display: flex; width: 100%; max-width: 340px; }
.search-form input {
  flex: 1 1 auto;
  min-width: 0;
  height: 44px;
  padding: 0 14px;
  background: #fff;
  border: 1.5px solid $(border.color);
  border-right: 0;
  border-radius: 8px 0 0 8px;
  font-size: 15px;
  color: $(text.color);
  transition: border-color 0.2s;
}
.search-form input:focus { border-color: $(accent.color); outline: none; }
.search-form button {
  flex: 0 0 48px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: $(primary.color);
  color: $(accent.color);
  border: 0;
  border-radius: 0 8px 8px 0;
  cursor: pointer;
}
.search-form button:hover { color: #fff; }

/* Post cards */
.post-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; }
@media (min-width: 640px) { .post-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .post-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 28px; } }
.post-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: #ffffff;
  border: 1px solid $(border.color);
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.07);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
}
.post-card:hover { transform: translateY(-3px); box-shadow: 0 10px 28px rgba(13, 28, 46, 0.12); }
.post-card-media {
  position: relative;
  display: block;
  padding-top: 56.25%;
  background: $(primary.color);
  overflow: hidden;
}
.post-card-media img,
.post-card-placeholder {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}
.post-card-media img { object-fit: cover; transition: transform 0.4s; }
.post-card:hover .post-card-media img { transform: scale(1.04); }
.post-card-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  color: $(accent.color);
  background: linear-gradient(135deg, $(primary.color), $(primary.soft.color));
}
.post-card-body { display: flex; flex-direction: column; flex: 1 1 auto; padding: 18px 20px 20px; }
.post-card-labels { margin-bottom: 10px; }
.post-card-title { margin: 0 0 8px; font-size: 19px; font-weight: 700; line-height: 1.35; color: $(primary.color); }
.post-card-title a {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-card-title a:hover { color: $(accent.color); }
.post-card-excerpt {
  margin: 0 0 14px;
  font-size: 14.5px;
  line-height: 1.6;
  color: $(muted.color);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.post-card-meta {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 4px 12px;
  margin-top: auto;
  padding-top: 6px;
  font-size: 12.5px;
  color: $(muted.color);
}

.empty-state {
  padding: 48px 24px;
  text-align: center;
  background: #ffffff;
  border: 1px solid $(border.color);
  border-radius: 12px;
}
.empty-state p { color: $(muted.color); }

/* Pagers */
.blog-pager-nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  margin-top: 36px;
}
.blog-pager-nav .older { margin-left: auto; }

/* Single post / page */
.post-single {
  background: #ffffff;
  border: 1px solid $(border.color);
  border-radius: 14px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.07);
  padding: 24px 20px 32px;
}
@media (min-width: 768px) { .post-single { padding: 44px 48px 48px; } }
.post-labels { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 14px; }
.post-title {
  margin: 0 0 12px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: clamp(34px, 5.5vw, 56px);
  line-height: 1.02;
  letter-spacing: 1px;
  color: $(primary.color);
}
.post-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  padding-bottom: 18px;
  margin-bottom: 26px;
  border-bottom: 1px solid $(border.color);
  font-size: 13.5px;
  color: $(muted.color);
}
.post-meta .post-author { font-weight: 700; color: $(primary.color); }
.post-meta .quick-edit-link { font-weight: 700; color: $(accent.color); }
.post-meta .sep { width: 4px; height: 4px; border-radius: 50%; background: $(accent.color); }

.post-body {
  font-size: 17px;
  line-height: 1.8;
  color: #2B3A4A;
  overflow-wrap: break-word;
}
.post-body h2, .post-body h3, .post-body h4 {
  margin: 1.6em 0 0.5em;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  letter-spacing: 1px;
  line-height: 1.1;
  color: $(primary.color);
}
.post-body h2 { font-size: 34px; }
.post-body h3 { font-size: 28px; }
.post-body h4 { font-size: 23px; }
.post-body a {
  color: $(primary.color);
  text-decoration: underline;
  text-decoration-color: $(accent.color);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
}
.post-body a:hover { color: $(accent.color); }
.post-body img { max-width: 100%; height: auto; border-radius: 8px; }
.post-body .separator a { text-decoration: none; }
@media (max-width: 600px) {
  .post-body .separator a { float: none !important; margin-left: 0 !important; margin-right: 0 !important; }
  .post-body .separator { text-align: center; }
}
.post-body iframe { max-width: 100%; border: 0; }
.post-body iframe[src*="youtube"], .post-body iframe[src*="vimeo"] {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
  border-radius: 8px;
}
body .widget .post-body ul, body .widget .post-body ol { margin: 0 0 1.2em; padding-left: 1.4em; }
body .widget .post-body ul { list-style: disc; }
body .widget .post-body ol { list-style: decimal; }
body .widget .post-body li { margin: 0.3em 0; padding: 0; }
.post-body blockquote {
  margin: 28px 0;
  padding: 18px 22px;
  background: rgba(0, 192, 168, 0.07);
  border-left: 4px solid $(accent.color);
  border-radius: 0 12px 12px 0;
  font-style: italic;
}
.post-body pre, .post-body code {
  font-family: Consolas, 'Courier New', monospace;
  font-size: 0.9em;
  background: $(page.background.color);
  border-radius: 6px;
}
.post-body code { padding: 2px 6px; }
.post-body pre { padding: 16px; overflow-x: auto; }
.post-body pre code { padding: 0; background: none; }
.post-body table { max-width: 100%; border-collapse: collapse; }
.post-body table:not(.tr-caption-container) { display: block; overflow-x: auto; }
.post-body table:not(.tr-caption-container) td,
.post-body table:not(.tr-caption-container) th { padding: 8px 12px; border: 1px solid $(border.color); }
.post-body .tr-caption { font-size: 13px; color: $(muted.color); }
.post-body hr { border: 0; height: 1px; background: $(border.color); margin: 2em 0; }

.post-share {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 36px;
  padding-top: 22px;
  border-top: 1px solid $(border.color);
}
.post-share-label {
  margin-right: 6px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-size: 22px;
  letter-spacing: 1px;
  color: $(primary.color);
}
.post-share a, .post-share button {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 8px 14px;
  background: transparent;
  border: 1.5px solid $(border.color);
  border-radius: 20px;
  font-size: 13px;
  font-weight: 700;
  color: $(primary.color);
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
}
.post-share a:hover, .post-share button:hover { border-color: $(accent.color); color: $(accent.color); }

/* Comments (Blogger's built-in markup) */
.post-single .comments {
  margin-top: 40px;
  padding-top: 28px;
  border-top: 1px solid $(border.color);
}
.comments .title, .comments h3, .comments h4 {
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: 28px;
  letter-spacing: 1px;
  color: $(primary.color);
}
.comments ol, .comments ul { list-style: none; margin: 0; padding: 0; }
.comments .comment { margin: 0 0 18px; }
.comments .avatar-image-container {
  float: left;
  width: 40px;
  height: 40px;
  max-height: 40px;
  border-radius: 50%;
  overflow: hidden;
  background: $(page.background.color);
}
.comments .avatar-image-container img { width: 100%; height: 100%; object-fit: cover; }
.comments .comment-block {
  margin-left: 52px;
  padding: 14px 16px;
  background: $(page.background.color);
  border: 1px solid $(border.color);
  border-radius: 12px;
}
.comments .comment-header .user, .comments .comment-header .user a { font-weight: 700; color: $(primary.color); }
.comments .datetime, .comments .datetime a { margin-left: 8px; font-size: 12px; color: $(muted.color); }
.comments .comment-content { margin: 6px 0; overflow-wrap: anywhere; }
.comments .comment-actions a,
.comments .continue a,
.comments .thread-toggle,
.comments .comment-reply {
  display: inline-block;
  margin-right: 12px;
  font-size: 13px;
  font-weight: 700;
  color: $(primary.color);
  cursor: pointer;
}
.comments .comment-actions a:hover, .comments .continue a:hover { color: $(accent.color); }
.comments .comment-replies { margin: 14px 0 0 20px; }
.comments .comment-replybox-thread, .comments .comment-replybox-single { margin-top: 12px; }
.comments iframe, #comment-editor { width: 100%; border: 0; }
@media (max-width: 480px) {
  .comments .comment-block { margin-left: 0; margin-top: 50px; }
  .comments .comment-replies { margin-left: 8px; }
}

#comments-block dt { margin: 18px 0 4px; font-weight: 700; color: $(primary.color); }
#comments-block dd { margin: 0 0 6px; }
#comments-block .comment-footer { font-size: 12px; color: $(muted.color); }
.comment-footer { margin: 16px 0 0; }

/* 404 */
.not-found { padding: 56px 20px; text-align: center; }
.not-found-code {
  margin: 0;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-size: clamp(96px, 20vw, 180px);
  line-height: 1;
  color: $(accent.color);
}
.not-found h1 { font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif; font-weight: 400; font-size: 40px; letter-spacing: 1px; color: $(primary.color); }
.not-found p { color: $(muted.color); }
.not-found .search-form { margin: 24px auto; }

/* ---------- Sidebar ---------- */
.pt-index .sidebar, .pt-archive .sidebar, .pt-error_page .sidebar { display: none; }
.sidebar .widget {
  margin-bottom: 24px;
  padding: 22px;
  background: #ffffff;
  border: 1px solid $(border.color);
  border-radius: 12px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.07);
}
.sidebar .widget:last-child { margin-bottom: 0; }
.sidebar .widget > .title, .sidebar .widget > h2, .sidebar .widget > h3,
.topics .widget > .title, .topics .widget > h2, .topics .widget > h3 {
  display: inline-block;
  margin: 0 0 16px;
  padding-bottom: 6px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: 24px;
  letter-spacing: 1px;
  line-height: 1;
  color: $(primary.color);
  border-bottom: 2px solid $(accent.color);
}
.sidebar a:hover { color: $(accent.color); }
.sidebar .PopularPosts .post,
.sidebar .PopularPosts li { margin: 0 0 14px; padding: 0 0 14px; border-bottom: 1px solid $(border.color); }
.sidebar .PopularPosts .post:last-child,
.sidebar .PopularPosts li:last-child { margin-bottom: 0; padding-bottom: 0; border-bottom: 0; }
.sidebar .PopularPosts .item-thumbnail { float: left; margin: 0 12px 4px 0; }
.sidebar .PopularPosts img { display: block; width: 64px; height: 64px; object-fit: cover; border-radius: 8px; }
.sidebar .PopularPosts .post-title, .sidebar .PopularPosts .item-title {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  color: $(primary.color);
}
.sidebar .PopularPosts .snippet-item, .sidebar .PopularPosts .item-snippet { font-size: 13px; color: $(muted.color); }
.sidebar input[type="text"], .sidebar input[type="search"] {
  width: 100%;
  height: 44px;
  padding: 0 12px;
  border: 1.5px solid $(border.color);
  border-radius: 8px;
}

/* ---------- Topics (homepage) ---------- */
.topics { display: none; padding: 0 0 72px; }
.topics .Label ul, .topics .cloud-label-widget-content, .sidebar .Label ul,
.sidebar .cloud-label-widget-content { display: flex; flex-wrap: wrap; gap: 10px; }
.topics .Label a, .sidebar .Label a {
  display: inline-block;
  padding: 9px 16px;
  background: #ffffff;
  border: 1px solid $(border.color);
  border-radius: 22px;
  font-size: 14px;
  font-weight: 700;
  color: $(primary.color);
  transition: border-color 0.2s, color 0.2s;
}
.topics .Label a:hover, .sidebar .Label a:hover { border-color: $(accent.color); color: $(accent.color); }
.topics .Label .label-count, .sidebar .Label .label-count { font-weight: 400; color: $(muted.color); }

/* ---------- Footer ---------- */
.site-footer {
  background: $(primary.color);
  color: #C9D2E0;
  border-top: 2px solid $(accent.color);
}
.footer-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 36px;
  padding: 56px 0 36px;
}
@media (min-width: 768px) { .footer-grid { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr); gap: 48px; } }
.site-footer .widget { margin-bottom: 20px; }
.site-footer .widget > .title, .site-footer .widget > h2, .site-footer .widget > h3 {
  display: inline-block;
  margin: 0 0 16px;
  padding-bottom: 6px;
  font-family: 'Bebas Neue', Impact, 'Arial Narrow', Arial, sans-serif;
  font-weight: 400;
  font-size: 24px;
  letter-spacing: 1px;
  line-height: 1;
  color: #fff;
  border-bottom: 2px solid $(accent.color);
}
.site-footer a { color: #C9D2E0; transition: color 0.2s, border-color 0.2s; }
.site-footer a:hover { color: $(accent.color); }
.site-footer .widget-content { font-size: 15px; line-height: 1.75; }
.site-footer .widget-content li { margin: 0 0 10px; }
#footer-connect .widget-content ul { display: flex; flex-wrap: wrap; gap: 8px; }
#footer-connect .widget-content li { margin: 0; }
#footer-connect .widget-content a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 20px;
  font-size: 13px;
  color: rgba(255, 255, 255, 0.75);
}
#footer-connect .widget-content a:hover { border-color: $(accent.color); color: $(accent.color); }
#footer-connect .social-icon { flex: 0 0 auto; color: $(accent.color); }
.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px 24px;
  padding: 18px 0 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  font-size: 13px;
  color: #8C99AB;
}
.footer-bottom p { margin: 0; }
.footer-bottom .widget { margin: 0; }
.footer-bottom .widget-content { font-size: 13px; }
@media (max-width: 600px) { .footer-bottom { justify-content: center; text-align: center; } }

/* ---------- Centred mobile layout (styling only; structure unchanged) ---------- */
/* Hero: centred whenever it is a single column */
@media (max-width: 959px) {
  .hero-inner { text-align: center; }
  .hero-title { padding-left: 0; padding-bottom: 18px; }
  .hero-title::before {
    top: auto;
    bottom: 0;
    left: 50%;
    width: 64px;
    height: 4px;
    margin-left: -32px;
    background: linear-gradient(to right, #1A7BC4, $(accent.color));
  }
  .hero-text { margin-left: auto; margin-right: auto; }
  .hero-main .widget-content ul { justify-content: center; }
}
/* Phones and small tablets */
@media (max-width: 767px) {
  .section-head { flex-direction: column; align-items: center; text-align: center; }
  .section-head .search-form { max-width: none; }
  .post-card-body { text-align: center; align-items: center; }
  .post-card-meta { justify-content: center; }
  .topics .container, .topics .widget { text-align: center; }
  .topics .Label ul, .topics .cloud-label-widget-content { justify-content: center; }
  .post-head { text-align: center; }
  .post-labels, .post-meta { justify-content: center; }
  .post-share { justify-content: center; }
  .post-share-label { flex-basis: 100%; margin: 0 0 4px; text-align: center; }
  .blog-pager-nav { flex-direction: column; }
  .blog-pager-nav .btn { width: 100%; }
  .blog-pager-nav .older { margin-left: 0; }
  .empty-state, .not-found { text-align: center; }
  .sidebar .widget > .title, .sidebar .widget > h2, .sidebar .widget > h3 { display: table; margin-left: auto; margin-right: auto; }
  .site-footer .footer-grid { text-align: center; }
  #footer-connect .widget-content ul { justify-content: center; }
  .header-cta .widget-content a { justify-content: center; }
}

/* ---------- Small screens ---------- */
@media (max-width: 380px) {
  body { font-size: 15px; }
  .brand-tagline { display: none; }
  .hero-main .widget-content ul { flex-direction: column; }
  .hero-main .widget-content a { width: 100%; }
}

/* ---------- Blogger Layout editor ---------- */
body#layout .site-header { position: static; }
body#layout .hero, body#layout .topics, body#layout .sidebar { display: block; }
body#layout .container { max-width: none; padding: 0; }
body#layout .header-inner, body#layout .hero-grid, body#layout .main-grid,
body#layout .footer-grid, body#layout .footer-bottom { display: block; }
body#layout .nav-drawer { display: block; position: static; }
body#layout .nav-toggle, body#layout .skip-link, body#layout .copyright { display: none; }
body#layout .hero-inner { min-height: 0; padding: 0; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

b:includable.script:
(function() {
  var items = ;
  var msgs = ;
  var config = ;
  // 
  var cursor = null;
  if (items && items.length > 0) {
    cursor = parseInt(items[items.length - 1].timestamp) + 1;
  }
  var bodyFromEntry = function(entry) {
    if (entry.gd$extendedProperty) {
      for (var k in entry.gd$extendedProperty) {
        if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
          return '<span class="deleted-comment">' + entry.content.$t + '</span>';
        }
      }
    }
    return entry.content.$t;
  }
  var parse = function(data) {
    cursor = null;
    var comments = [];
    if (data && data.feed && data.feed.entry) {
      for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
        var comment = {};
        // comment ID, parsed out of the original id format
        var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
        comment.id = id ? id[2] : null;
        comment.body = bodyFromEntry(entry);
        comment.timestamp = Date.parse(entry.published.$t) + '';
        if (entry.author && entry.author.constructor === Array) {
          var auth = entry.author[0];
          if (auth) {
            comment.author = {
              name: (auth.name ? auth.name.$t : undefined),
              profileUrl: (auth.uri ? auth.uri.$t : undefined),
              avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
            };
          }
        }
        if (entry.link) {
          if (entry.link[2]) {
            comment.link = comment.permalink = entry.link[2].href;
          }
          if (entry.link[3]) {
            var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
            if (pid && pid[1]) {
              comment.parentId = pid[1];
            }
          }
        }
        comment.deleteclass = 'item-control blog-admin';
        if (entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
              comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
            } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
              comment.displayTime = entry.gd$extendedProperty[k].value;
            }
          }
        }
        comments.push(comment);
      }
    }
    return comments;
  };
  var paginator = function(callback) {
    if (hasMore()) {
      var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
      if (cursor) {
        url += '&published-min=' + new Date(cursor).toISOString();
      }
      window.bloggercomments = function(data) {
        var parsed = parse(data);
        cursor = parsed.length < 50 ? null
        : parseInt(parsed[parsed.length - 1].timestamp) + 1
        callback(parsed);
        window.bloggercomments = null;
      }
      url += '&callback=bloggercomments';
      var script = document.createElement('script');
      script.type = 'text/javascript';
      script.src = url;
      document.getElementsByTagName('head')[0].appendChild(script);
    }
  };
  var hasMore = function() {
    return !!cursor;
  };
  var getMeta = function(key, comment) {
    if ('iswriter' == key) {
      var matches = !!comment.author
      && comment.author.name == config.authorName
      && comment.author.profileUrl == config.authorUrl;
      return matches ? 'true' : '';
    } else if ('deletelink' == key) {
      return config.baseUri + '/delete-comment.g?blogID='
      + config.blogId + '&postID=' + comment.id;
    } else if ('deleteclass' == key) {
      return comment.deleteclass;
    }
    return '';
  };
  var replybox = null;
  var replyUrlParts = null;
  var replyParent = undefined;
  var onReply = function(commentId, domId) {
    if (replybox == null) {
      // lazily cache replybox, and adjust to suit this style:
      replybox = document.getElementById('comment-editor');
      if (replybox != null) {
        replybox.height = '250px';
        replybox.style.display = 'block';
        replyUrlParts = replybox.src.split('#');
      }
    }
    if (replybox && (commentId !== replyParent)) {
      document.getElementById(domId).insertBefore(replybox.parentNode, null);
      replybox.src = replyUrlParts[0]
      + (commentId ? '&parentID=' + commentId : '')
      + '#' + replyUrlParts[1];
      replyParent = commentId;
    }
  };
  var hash = (window.location.hash || '#').substring(1);
  var startThread, targetComment;
  if (/^comment-form_/.test(hash)) {
    startThread = hash.substring('comment-form_'.length);
  } else if (/^c[0-9]+$/.test(hash)) {
    targetComment = hash.substring(1);
  }
  // Configure commenting API:
  var configJso = {
    'maxDepth': config.maxThreadDepth
  };
  var provider = {
    'id': config.postId,
    'data': items,
    'loadNext': paginator,
    'hasMore': hasMore,
    'getMeta': getMeta,
    'onReply': onReply,
    'rendered': true,
    'initComment': targetComment,
    'initReplyThread': startThread,
    'config': configJso,
    'messages': msgs
  };
  var render = function() {
    if (window.goog && window.goog.comments) {
      var holder = document.getElementById('comment-holder');
      window.goog.comments.render(holder, provider);
    }
  };
  // render now, or queue to render when library loads:
  if (window.goog && window.goog.comments) {
    render();
  } else {
    window.goog = window.goog || {};
    window.goog.comments = window.goog.comments || {};
    window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
    window.goog.comments.loadQueue.push(render);
  }
})();
//

body.script:
//
// River Musa theme behaviour: mobile menu, sticky-header shadow, brand initials,
// hero title accent, copy-link button and footer year. No dependencies.
(function () {
  'use strict';
  var doc = document;
  var root = doc.documentElement;

  // Sub-menus: in the Link List, a link whose name starts with "_" becomes a
  // sub-item of the closest link above it without "_".
  var menuList = doc.querySelector('.site-nav .widget-content > ul');
  if (menuList) {
    var parentItem = null;
    var menuItems = Array.prototype.slice.call(menuList.children);
    for (var mi = 0; mi < menuItems.length; mi++) {
      var item = menuItems[mi];
      var link = item.querySelector('a');
      if (!link) continue;
      var label = link.textContent.replace(/^\s+/, '');
      if (label.charAt(0) === '_' && parentItem) {
        link.textContent = label.replace(/^_+\s*/, '');
        var sub = parentItem.querySelector('ul.sub-menu');
        if (!sub) {
          sub = doc.createElement('ul');
          sub.className = 'sub-menu';
          parentItem.appendChild(sub);
          parentItem.classList.add('has-sub');
          var subToggle = doc.createElement('button');
          subToggle.type = 'button';
          subToggle.className = 'sub-toggle';
          subToggle.setAttribute('aria-expanded', 'false');
          subToggle.setAttribute('aria-label', 'Show ' + parentItem.querySelector('a').textContent.trim() + ' pages');
          subToggle.innerHTML = '<svg aria-hidden="true" fill="none" height="16" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2.4" viewBox="0 0 24 24" width="16"><polyline points="6 9 12 15 18 9"/></svg>';
          parentItem.insertBefore(subToggle, sub);
        }
        sub.appendChild(item);
      } else {
        if (label.charAt(0) === '_') link.textContent = label.replace(/^_+\s*/, '');
        parentItem = item;
      }
    }
    menuList.addEventListener('click', function (e) {
      var btn = e.target.closest ? e.target.closest('.sub-toggle') : null;
      if (!btn) return;
      var li = btn.parentNode;
      var open = !li.classList.contains('open');
      var siblings = menuList.querySelectorAll('li.has-sub.open');
      for (var si = 0; si < siblings.length; si++) {
        siblings[si].classList.remove('open');
        siblings[si].querySelector('.sub-toggle').setAttribute('aria-expanded', 'false');
      }
      if (open) li.classList.add('open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  }

  // Social links: add an icon based on the link's address
  var socialIcons = {
    youtube: '<rect x="2" y="5" width="20" height="14" rx="4"/><polygon points="10 9 15 12 10 15 10 9"/>',
    tiktok: '<path d="M14 3v11.5a3.5 3.5 0 1 1-3.5-3.5"/><path d="M14 3c.6 2.6 2.6 4.6 5 4.8"/>',
    instagram: '<rect x="2" y="2" width="20" height="20" rx="5"/><circle cx="12" cy="12" r="4"/><line x1="17.5" x2="17.51" y1="6.5" y2="6.5"/>',
    linkedin: '<path d="M16 8a6 6 0 0 1 6 6v7h-4v-7a2 2 0 0 0-4 0v7h-4v-7a6 6 0 0 1 6-6z"/><rect x="2" y="9" width="4" height="12"/><circle cx="4" cy="4" r="2"/>',
    facebook: '<path d="M18 2h-3a5 5 0 0 0-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 0 1 1-1h3z"/>',
    x: '<path d="M4 4l16 16"/><path d="M20 4L4 20"/>',
    whatsapp: '<path d="M21 11.5a8.4 8.4 0 0 1-12.4 7.4L3 21l2.1-5.4A8.4 8.4 0 1 1 21 11.5z"/>',
    spotify: '<circle cx="12" cy="12" r="10"/><path d="M7 9.5c3.5-1 7.5-.7 10.5 1"/><path d="M7.5 12.7c2.9-.8 6-.5 8.5.9"/><path d="M8 15.8c2.3-.6 4.6-.4 6.6.7"/>',
    podcast: '<circle cx="12" cy="11" r="3"/><path d="M8.5 16.5a6 6 0 1 1 7 0"/><path d="M12 14v8"/>',
    email: '<rect x="2" y="4" width="20" height="16" rx="2"/><polyline points="22 6 12 13 2 6"/>',
    link: '<path d="M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7"/><path d="M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>'
  };
  function socialType(href) {
    var h = (href || '').toLowerCase();
    if (h.indexOf('mailto:') === 0) return 'email';
    if (/youtube\.com|youtu\.be/.test(h)) return 'youtube';
    if (/tiktok\.com/.test(h)) return 'tiktok';
    if (/instagram\.com/.test(h)) return 'instagram';
    if (/linkedin\.com/.test(h)) return 'linkedin';
    if (/facebook\.com|fb\.com|fb\.me/.test(h)) return 'facebook';
    if (/(^|\/\/|\.)(x|twitter)\.com/.test(h)) return 'x';
    if (/whatsapp\.com|wa\.me/.test(h)) return 'whatsapp';
    if (/spotify\.com/.test(h)) return 'spotify';
    if (/podcasts\.apple\.com|anchor\.fm|podbean|buzzsprout/.test(h)) return 'podcast';
    return 'link';
  }
  var socialLinks = doc.querySelectorAll('#footer-connect .widget-content a');
  for (var so = 0; so < socialLinks.length; so++) {
    var sl = socialLinks[so];
    if (sl.querySelector('svg')) continue;
    var svg = '<svg aria-hidden="true" class="social-icon" fill="none" height="18" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" stroke-width="2" viewBox="0 0 24 24" width="18">' + socialIcons[socialType(sl.getAttribute('href'))] + '</svg>';
    sl.insertAdjacentHTML('afterbegin', svg);
    if (/^https?:/i.test(sl.getAttribute('href') || '')) {
      sl.setAttribute('target', '_blank');
      sl.setAttribute('rel', 'noopener');
    }
  }

  // Host card video: a YouTube link (or YouTube embed) in the host card gadget
  // replaces the microphone with the video. The player loads only on play.
  var hostCard = doc.querySelector('.host-card');
  var hostRole = hostCard ? hostCard.querySelector('.host-role') : null;
  var ytPattern = /(?:youtube\.com\/(?:watch\?(?:[^\s"'<>]*&)?v=|embed\/|shorts\/|live\/)|youtu\.be\/)([A-Za-z0-9_-]{11})[^\s"'<>]*/;
  function findVideoId(node) {
    var frames = node.querySelectorAll('iframe');
    for (var fi = 0; fi < frames.length; fi++) {
      var fm = ytPattern.exec(frames[fi].getAttribute('src') || '');
      if (fm) { frames[fi].parentNode.removeChild(frames[fi]); return fm[1]; }
    }
    var anchors = node.querySelectorAll('a');
    for (var ai = 0; ai < anchors.length; ai++) {
      var am = ytPattern.exec(anchors[ai].getAttribute('href') || '');
      if (am) { anchors[ai].parentNode.removeChild(anchors[ai]); return am[1]; }
    }
    var walker = doc.createTreeWalker(node, 4, null, false);
    var textNode;
    while ((textNode = walker.nextNode())) {
      var tm = ytPattern.exec(textNode.nodeValue);
      if (tm) {
        textNode.nodeValue = textNode.nodeValue.replace(/\S*(?:youtube\.com|youtu\.be)\S*/, '').replace(/\s+$/, '');
        return tm[1];
      }
    }
    return null;
  }
  if (hostCard && hostRole) {
    var videoId = findVideoId(hostRole);
    if (videoId) {
      var paras = hostRole.querySelectorAll('p, div');
      for (var pi = 0; pi < paras.length; pi++) {
        if (!paras[pi].textContent.trim() && !paras[pi].querySelector('img')) paras[pi].parentNode.removeChild(paras[pi]);
      }
      var avatarSlot = hostCard.querySelector('.host-avatar');
      var video = doc.createElement('div');
      video.className = 'host-video';
      var playBtn = doc.createElement('button');
      playBtn.type = 'button';
      playBtn.className = 'host-video-play';
      playBtn.setAttribute('aria-label', 'Play video');
      var thumb = doc.createElement('img');
      thumb.alt = '';
      thumb.loading = 'lazy';
      thumb.src = 'https://i.ytimg.com/vi/' + videoId + '/hqdefault.jpg';
      playBtn.appendChild(thumb);
      playBtn.insertAdjacentHTML('beforeend', '<span class="host-video-icon"><svg aria-hidden="true" fill="currentColor" height="28" viewBox="0 0 24 24" width="28"><polygon points="8 5 19 12 8 19 8 5"/></svg></span>');
      playBtn.addEventListener('click', function () {
        var frame = doc.createElement('iframe');
        frame.src = 'https://www.youtube-nocookie.com/embed/' + videoId + '?autoplay=1&rel=0';
        frame.title = 'Video';
        frame.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture');
        frame.setAttribute('allowfullscreen', '');
        video.innerHTML = '';
        video.appendChild(frame);
      });
      video.appendChild(playBtn);
      if (avatarSlot) avatarSlot.parentNode.replaceChild(video, avatarSlot);
      else hostCard.insertBefore(video, hostCard.firstChild);
      hostCard.classList.add('has-video');
    }
  }

  // Mobile menu
  var header = doc.getElementById('site-header');
  var toggle = doc.getElementById('nav-toggle');
  var drawer = doc.getElementById('site-nav');
  var desktop = window.matchMedia ? window.matchMedia('(min-width: 1024px)') : null;

  // Dimmed backdrop behind the open menu; tapping it closes the menu
  var backdrop = null;
  if (header) {
    backdrop = doc.createElement('div');
    backdrop.className = 'nav-backdrop';
    backdrop.setAttribute('aria-hidden', 'true');
    doc.body.appendChild(backdrop);
    backdrop.addEventListener('click', function () { setMenu(false); });
  }

  function setMenu(open) {
    if (!header || !toggle) return;
    if (open) {
      header.classList.add('nav-open');
      root.classList.add('nav-locked');
      if (backdrop) backdrop.classList.add('is-visible');
    } else {
      header.classList.remove('nav-open');
      root.classList.remove('nav-locked');
      if (backdrop) backdrop.classList.remove('is-visible');
    }
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  }

  if (header && toggle && drawer) {
    toggle.addEventListener('click', function () {
      setMenu(!header.classList.contains('nav-open'));
    });
    // Close after choosing a link (also covers same-page #anchors)
    drawer.addEventListener('click', function (e) {
      var t = e.target;
      while (t && t !== drawer) {
        if (t.tagName === 'A') { setMenu(false); return; }
        t = t.parentNode;
      }
    });
    doc.addEventListener('keydown', function (e) {
      if ((e.key === 'Escape' || e.key === 'Esc') && header.classList.contains('nav-open')) {
        setMenu(false);
        toggle.focus();
      }
    });
    window.addEventListener('pageshow', function () { setMenu(false); });
    if (desktop) {
      var onChange = function () { if (desktop.matches) setMenu(false); };
      if (desktop.addEventListener) desktop.addEventListener('change', onChange);
      else if (desktop.addListener) desktop.addListener(onChange);
    }
  }

  // Shadow under the sticky header once the page scrolls
  if (header) {
    var ticking = false;
    var onScroll = function () {
      if (ticking) return;
      ticking = true;
      window.requestAnimationFrame(function () {
        if (window.pageYOffset > 8) header.classList.add('is-scrolled');
        else header.classList.remove('is-scrolled');
        ticking = false;
      });
    };
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  // Initials in the round brand mark when no logo image is set ("The River Musa Show" -> "RM")
  var mark = doc.querySelector('.brand-mark');
  var name = doc.querySelector('.brand-name');
  if (mark && name && !mark.querySelector('img')) {
    var skip = { the: 1, a: 1, an: 1 };
    var words = name.textContent.trim().split(/\s+/).filter(function (w) {
      return w && !skip[w.toLowerCase()];
    });
    mark.textContent = words.slice(0, 2).map(function (w) { return w.charAt(0); }).join('').toUpperCase();
  }

  // Hero title: first word white, the rest in the accent colour
  var title = doc.querySelector('.hero-title');
  if (title && title.children.length === 0) {
    var parts = title.textContent.trim().split(/\s+/);
    if (parts.length > 1) {
      title.textContent = parts[0] + ' ';
      var accent = doc.createElement('span');
      accent.className = 'accent';
      accent.textContent = parts.slice(1).join(' ');
      title.appendChild(accent);
    }
  }

  // Card images: ask Blogger/YouTube for a 16:9 size instead of the full image or a 72px thumbnail
  var googleImage = /^https?:\/\/([a-z0-9-]+\.)*(googleusercontent\.com|blogspot\.com|bp\.blogspot\.com|ggpht\.com)\//i;
  var youtubeThumb = /^(https?:\/\/(img\.youtube\.com|i\.ytimg\.com)\/vi\/[^/]+\/)[a-z]*default\.jpg$/i;
  var cardImgs = doc.querySelectorAll('img.js-resize');
  for (var c = 0; c < cardImgs.length; c++) {
    var src = cardImgs[c].getAttribute('src') || '';
    var sized = src;
    if (googleImage.test(src)) {
      sized = src
        .replace(/\/s\d+(-[a-z]+)*\//i, '/w720-h405-c/')
        .replace(/\/w\d+-h\d+(-[a-z]+)*\//i, '/w720-h405-c/')
        .replace(/=s\d+(-[a-z]+)*$/i, '=w720-h405-c')
        .replace(/=w\d+-h\d+(-[a-z]+)*$/i, '=w720-h405-c');
    } else if (youtubeThumb.test(src)) {
      sized = src.replace(youtubeThumb, '$1hqdefault.jpg');
    }
    if (sized !== src) cardImgs[c].setAttribute('src', sized);
  }

  // Dates: show "12 October 2026" style dates whatever the blog's timestamp format is
  var dates = doc.querySelectorAll('time.js-date');
  for (var d = 0; d < dates.length; d++) {
    var when = new Date(dates[d].getAttribute('datetime'));
    if (!isNaN(when.getTime())) {
      dates[d].textContent = when.toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
    }
  }

  // Host card: a photo placed in the gadget's content replaces the microphone icon
  var hostImg = doc.querySelector('.host-role img');
  var avatar = doc.querySelector('.host-avatar');
  if (hostImg && avatar) {
    avatar.innerHTML = '';
    avatar.appendChild(hostImg);
  }

  // Copy-link share button
  var copyBtns = doc.querySelectorAll('[data-copy-url]');
  for (var i = 0; i < copyBtns.length; i++) {
    copyBtns[i].addEventListener('click', function () {
      var btn = this;
      var url = btn.getAttribute('data-copy-url');
      var done = function () {
        var label = btn.textContent;
        btn.textContent = 'Copied';
        setTimeout(function () { btn.textContent = label; }, 1600);
      };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(done, function () { window.prompt('Copy this link:', url); });
      } else {
        window.prompt('Copy this link:', url);
      }
    });
  }

  // Footer year
  var years = doc.querySelectorAll('.js-year');
  for (var y = 0; y < years.length; y++) years[y].textContent = String(new Date().getFullYear());
})();
